// Normalizes incoming Instagram message data for Client Bunny
const body = $input.first().json.body || $input.first().json;

// Handle both Meta Graph API format and generic webhook payloads
let senderId = body.instagram_username || body.username || (body.entry && body.entry[0]?.messaging && body.entry[0].messaging[0]?.sender?.id) || 'instagram_user';
let senderName = body.first_name || body.name || `@${senderId}`;
let messageText = body.message || body.text || (body.entry && body.entry[0]?.messaging && body.entry[0].messaging[0]?.message?.text) || '[Instagram DM]';

return [{
  json: {
    channel: 'instagram',
    instagram_username: senderId,
    first_name: senderName,
    message: messageText,
    timestamp: new Date().toISOString()
  }
}];
